import {
  Column,
  CreateDateColumn,
  Entity,
  Index,
  PrimaryColumn,
} from 'typeorm';
import { OrgScopedEntity } from '~/tenancy/org-scoped.entity';
import type { FilePurposeName } from '../file-purposes';

/**
 * Metadata of one object in storage. The bytes live in S3 under `key`;
 * owning records (student photo, document, export job) point at `id`.
 */
@Entity('files')
@Index('uq_files_key', ['key'], { unique: true })
export class StoredFile extends OrgScopedEntity {
  /** Generated by the app, because it is part of the storage key. */
  @PrimaryColumn('uuid')
  id: string;

  @Column({ type: 'varchar', length: 512 })
  key: string;

  @Column({ name: 'original_name', type: 'varchar', length: 255 })
  originalName: string;

  /** Detected from the content, not the client's claim. */
  @Column({ type: 'varchar', length: 127 })
  mime: string;

  @Column({ type: 'int' })
  size: number;

  @Column({ type: 'char', length: 64 })
  sha256: string;

  @Column({ type: 'varchar', length: 32 })
  purpose: FilePurposeName;

  @Column({ name: 'uploaded_by', type: 'uuid', nullable: true })
  uploadedBy: string | null;

  @CreateDateColumn({ name: 'created_at' })
  createdAt: Date;
}
